public class TrendingService
{
    private readonly Dictionary<string, int> _hashtagCounts = new();
    private readonly Timer _timer;

    public void RecordTweet(Tweet tweet)
    {
        var hashtags = Regex.Matches(tweet.Content, "#\w+")
            .Cast<Match>()
            .Select(m => m.Value.ToLowerInvariant());

        foreach (var tag in hashtags)
        {
            _hashtagCounts[tag] = _hashtagCounts.GetValueOrDefault(tag) + 1;
        }
    }

    public IEnumerable<(string Tag, int Count)> GetTrending(int top = 10)
    {
        return _hashtagCounts
            .OrderByDescending(kv => kv.Value)
            .Take(top)
            .Select(kv => (kv.Key, kv.Value));
    }
}

public class SearchService
{
    private readonly InvertedIndex _index = new();

    public void Index(Tweet tweet)
    {
        var words = tweet.Content.ToLowerInvariant().Split(' ');
        foreach (var word in words)
            _index.Add(word, tweet.Id);
    }

    public IEnumerable<Tweet> Search(string query)
    {
        var words = query.ToLowerInvariant().Split(' ');
        return words.SelectMany(w => _index.Lookup(w))
            .Distinct()
            .Select(id => _tweets[id]);
    }
}
